// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 seedDrugs) public {
        // Bound seedDrugs to avoid overflow; require non-zero for meaningful test
        vm.assume(seedDrugs > 0 && seedDrugs < 1e36);
        // Fund contract and caller
        vm.deal(address(c), initialBalance % 1e18);
        vm.deal(caller, initialBalance % 1e18 + 1 ether);
        // Seed the market
        vm.prank(address(c));
        c.seedMarket(seedDrugs);
        // Give caller some free kilos to produce drugs
        vm.prank(caller);
        c.getFreeKilo();
        // Warp time so that drugs accumulate
        vm.warp(block.timestamp + 86401);
        // Now caller sells drugs
        vm.prank(caller);
        c.sellDrugs();
        // After sell, claimedDrugs[caller] must be zero
        assertTrue(c.claimedDrugs(caller) == 0);
    }
}

